// ZIP_STORED only: generated by Assisted Scan exporter, no decompression dependency.
const MAX=10*1024*1024;
const decoder=new TextDecoder('utf-8',{fatal:true});
export function crc32(data){let c=0xffffffff;for(const b of data){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
function fail(message){throw Error(message)}
export function decodeStoredZip(bytes){if(bytes.byteLength>MAX)fail('ZIP túl nagy');const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),files=new Map();let i=0;while(i+4<=bytes.length&&v.getUint32(i,true)===0x04034b50){if(i+30>bytes.length)fail('Sérült ZIP fejléc');const flags=v.getUint16(i+6,true),method=v.getUint16(i+8,true),crc=v.getUint32(i+14,true),packed=v.getUint32(i+18,true),size=v.getUint32(i+22,true),nameLen=v.getUint16(i+26,true),extraLen=v.getUint16(i+28,true),nameEnd=i+30+nameLen,start=nameEnd+extraLen,end=start+size;if(flags&~0x800||method!==0||packed!==size)fail('Csak tömörítés nélküli Assisted Scan ZIP támogatott');if(end>bytes.length||files.size>=101||nameLen===0)fail('Sérült vagy túl nagy ZIP');const name=decoder.decode(bytes.subarray(i+30,nameEnd));if(!/^(manifest\.json|portraits\/[A-Za-z0-9_-]+\.(jpg|jpeg|png|webp))$/.test(name)||files.has(name))fail('Tiltott vagy ismétlődő fájlnév');const data=bytes.subarray(start,end);if(crc32(data)!==crc)fail('Sérült ZIP állomány');files.set(name,data);i=end}if(i+4>bytes.length||v.getUint32(i,true)!==0x02014b50||!files.has('manifest.json'))fail('Hiányos ZIP vagy manifest');return files}
const b64=bytes=>{let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(raw)};
export function parseStoredPackage(bytes){const files=decodeStoredZip(bytes),raw=JSON.parse(decoder.decode(files.get('manifest.json')));if(raw.format!=='cl-assisted-scan-v2'||!Array.isArray(raw.portraits))fail('Típusozott manifest szükséges');const used=new Set(['manifest.json']);raw.portraits=raw.portraits.map(p=>{if(typeof p.imagePath!=='string'||!files.has(p.imagePath)||used.has(p.imagePath)||p.image||p.playerId)fail('Hibás portréhivatkozás');const data=files.get(p.imagePath);if(data.length>130000)fail('Portré túl nagy');used.add(p.imagePath);const mime=p.imagePath.endsWith('.png')?'png':p.imagePath.endsWith('.webp')?'webp':'jpeg';return {name:p.name,image:`data:image/${mime};base64,${b64(data)}`}});if(used.size!==files.size)fail('Nem hivatkozott ZIP állomány');return raw}
export async function openScanPackage(file){if(file.size>MAX)fail('Túl nagy importfájl');if(/\.zip$/i.test(file.name??''))return parseStoredPackage(new Uint8Array(await file.arrayBuffer()));return JSON.parse(await file.text())}
